import React, { useEffect, useState } from "react";

const API_KEY = "1e6e7e2e7e6e4e2e8e7e2e7e2e7e2e7e"; // Reemplaza por tu API key real si tienes una
const CITY = "Córdoba,AR";

function getWeatherIcon(condition) {
  if (!condition) return "☀️";
  const c = condition.toLowerCase();
  if (c.includes("rain")) return "🌧️";
  if (c.includes("cloud")) return "☁️";
  if (c.includes("clear")) return "☀️";
  if (c.includes("storm")) return "⛈️";
  if (c.includes("snow")) return "❄️";
  if (c.includes("fog")) return "🌫️";
  return "☀️";
}

export default function WeatherCard() {
  const [weather, setWeather] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchWeather = async () => {
    setLoading(true);
    setError(null);
    try {
      // Usamos Open-Meteo API (sin key) para demo, puedes cambiar a OpenWeatherMap si tienes key
      const res = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=-31.4167&longitude=-64.1833&current_weather=true&hourly=apparent_temperature,temperature_2m_max,temperature_2m_min&timezone=America%2FArgentina%2FCordoba`
      );
      const data = await res.json();
      setWeather({
        temp: Math.round(data.current_weather.temperature),
        feels_like: Math.round(data.hourly.apparent_temperature[0]),
        min: Math.round(data.hourly.temperature_2m_min[0]),
        max: Math.round(data.hourly.temperature_2m_max[0]),
        condition: data.current_weather.weathercode === 0 ? "Soleado" : "Variable",
        icon: getWeatherIcon("Soleado"),
        time: new Date(data.current_weather.time),
      });
    } catch (e) {
      setError("No se pudo obtener el clima");
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchWeather();
    const interval = setInterval(fetchWeather, 60000); // Actualiza cada minuto
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div className="rounded-2xl bg-white/30 shadow-lg p-6 w-full max-w-xs mx-auto animate-pulse">
        <div className="h-8 bg-gray-200 rounded w-1/2 mb-4"></div>
        <div className="h-4 bg-gray-200 rounded w-1/3 mb-2"></div>
        <div className="h-4 bg-gray-200 rounded w-2/3"></div>
      </div>
    );
  }
  if (error || !weather) {
    return (
      <div className="rounded-2xl bg-white/30 shadow-lg p-6 w-full max-w-xs mx-auto text-center text-red-600">
        {error || "No hay datos de clima"}
      </div>
    );
  }

  return (
    <div className="rounded-2xl bg-[#1a274e]/80 shadow-xl p-6 w-full max-w-xs mx-auto text-white flex flex-col gap-2" style={{backdropFilter: 'blur(6px)'}}>
      <div className="flex justify-between items-start mb-2">
        <span className="text-6xl font-extrabold leading-none">{weather.temp}°</span>
        <span className="text-sm opacity-80 mt-1">{weather.time.toLocaleString('es-AR', { weekday: 'short', hour: '2-digit', minute: '2-digit' })}</span>
      </div>
      <div className="text-2xl font-bold flex items-center gap-2 mb-1">
        {weather.condition} <span>{weather.icon}</span>
      </div>
      <div className="text-sm opacity-90 mb-1">
        <span className="align-middle">↑ {weather.max}° / ↓ {weather.min}°</span>
      </div>
      <div className="text-sm opacity-80">Sensación Térmica {weather.feels_like}°</div>
    </div>
  );
}
